// Bewässerung-------------------------------------
schedule("* * * * * *", async function () {
  if (getState("0_userdata.0.Bewässerung.Aktiv").val) {
    if (getState("0_userdata.0.Bewässerung.Zeitzone1").val) {
      setState("0_userdata.0.Bewässerung.Intervall"/*Intervall*/, (parseFloat(getState("0_userdata.0.Bewässerung.Grundintervall").val) * getState("0_userdata.0.Bewässerung.Zeitzone1_Multiplikator").val));
    } else if (getState("0_userdata.0.Bewässerung.Zeitzone2").val) {
      setState("0_userdata.0.Bewässerung.Intervall"/*Intervall*/, (parseFloat(getState("0_userdata.0.Bewässerung.Grundintervall").val) * getState("0_userdata.0.Bewässerung.Zeitzone2_Multiplikator").val));
    } else if (getState("0_userdata.0.Bewässerung.Zeitzone3").val) {
      setState("0_userdata.0.Bewässerung.Intervall"/*Intervall*/, (parseFloat(getState("0_userdata.0.Bewässerung.Grundintervall").val) * getState("0_userdata.0.Bewässerung.Zeitzone3_Multiplikator").val));
    } else if (getState("0_userdata.0.Bewässerung.Zeitzone4").val) {
      setState("0_userdata.0.Bewässerung.Intervall"/*Intervall*/, (parseFloat(getState("0_userdata.0.Bewässerung.Grundintervall").val) * getState("0_userdata.0.Bewässerung.Zeitzone4_Multiplikator").val));
    } else {
      setState("0_userdata.0.Bewässerung.Intervall"/*Intervall*/, (parseFloat(getState("0_userdata.0.Bewässerung.Grundintervall").val) * 1), true);
    }
    setState("0_userdata.0.Bewässerung.Timer"/*Timer*/, (parseFloat(getState("0_userdata.0.Bewässerung.Timer").val) + 1));
    if (getState("0_userdata.0.Bewässerung.Timer").val >= parseFloat(getState("0_userdata.0.Bewässerung.Intervall").val) * 60) {
      console.log('RUN');
      setState("linktap.0.03444023004B1200.13414023004B1200.InstantModeDuration"/*Duration for instant mode (min.1  - max. 1439)*/, getState("0_userdata.0.Bewässerung.Dauer").val);
      setState("linktap.0.03444023004B1200.13414023004B1200.StartInstantMode"/*Starts instant mode. (Set duration in state 'InstantModeDuration'*/, true);
      setState("0_userdata.0.Bewässerung.Timer"/*Timer*/, 0);
    }
  } else if (getState("0_userdata.0.Bewässerung.Timer").val != 0) {
    console.log('STOP');
    setState("0_userdata.0.Bewässerung.Timer"/*Timer*/, 0);
    setState("linktap.0.03444023004B1200.13414023004B1200.StopInstantMode"/*Stops instant / eco instant mode*/, true);
  }
});
// Kommentar
on({id: "0_userdata.0.Bewässerung.Grunddauer"/*Grunddauer*/, change: "ne"}, async function (obj) {
  var value = obj.state.val;
  var oldValue = obj.oldState.val;
  setState("0_userdata.0.Bewässerung.Dauer"/*Dauer*/, getState("0_userdata.0.Bewässerung.Grunddauer").val);
});
on({id: "0_userdata.0.Bewässerung.Grundintervall"/*Grundintervall*/, change: "ne"}, async function (obj) {
  var value = obj.state.val;
  var oldValue = obj.oldState.val;
  setState("0_userdata.0.Bewässerung.Intervall"/*Intervall*/, getState("0_userdata.0.Bewässerung.Grundintervall").val);
});


